def replace_exact(doc, old, new):
    hits = [p for p in doc.paragraphs if p.text == old]
    if len(hits) != 1:
        raise RuntimeError(f'Expected one exact paragraph, found {len(hits)} for: {old[:80]}')
    p = hits[0]
    style = p.style
    p.text = new
    p.style = style

